        y: canvas.height / 2,
        radius: 50,
        length: 100
      };

      document.getElementById('start-button').addEventListener('click', startSimulation);
    }

    function startSimulation() {
      isRunning = true;
      angle = parseFloat(document.getElementById('initial-angle').value);
      velocity = 0;
